type Monitor = { id:string; enabled:boolean; interval_minutes:number; timeout_ms:number; failure_threshold:number; expected_status_min:number; expected_status_max:number; last_status:string; last_response_ms?:number; last_checked_at?:string };
type AuditRun = { id:string; status:string; score?:number; coverage?:number; page_url?:string; created_at:string; completed_at?:string; duration_ms?:number; audit_results?:any[] };
type Property = { id:string; workspace_id?:string; name:string; url:string; canonical_host:string; verification_status:string; tracking_id:string; tracking_last_received_at?:string; uptime_monitors?:Monitor[]; audit_runs?:AuditRun[] };
type Bootstrap = { profile:any; accounts:any[]; workspaces:any[]; properties:Property[]; incidents:any[]; notifications:any[] };
type Notify = (message:string)=>void;

async function api<T>(session: Session, path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, { ...init, headers: { 'content-type':'application/json', authorization:`Bearer ${session.access_token}`, ...init?.headers } });
  const body: any = await res.json().catch(()=>({}));
  if (!res.ok) throw new Error(body.error || 'Request failed');
  return body as T;
}

