export function App(){
  const fixture = import.meta.env.DEV && new URLSearchParams(location.search).has('fixture');
  const [session,setSession]=useState<Session|null>(null); const [ready,setReady]=useState(fixture);
  useEffect(()=>{if(fixture)return; supabase.auth.getSession().then(({data})=>{setSession(data.session);setReady(true)}); const {data}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s)); return()=>data.subscription.unsubscribe();},[fixture]);
  if(!ready) return <Splash/>;
  if(fixture) return <Routes><Route path="*" element={<Shell session={null} data={fixtureData} reload={()=>{}} fixture/>}/></Routes>;
  return <Routes><Route path="/auth/*" element={session?<Navigate to="/"/>:<Auth/>}/><Route path="/*" element={session?<Workspace session={session}/>:<Navigate to="/auth/sign-in"/>}/></Routes>;
}

function Auth(){
  const nav=useNavigate(); const loc=useLocation(); const mode=loc.pathname.split('/').pop()||'sign-in';
  const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [message,setMessage]=useState(''); const [busy,setBusy]=useState(false);
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setMessage('');try{
    if(mode==='register'){const {error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:`${location.origin}/auth/confirmed`}});if(error)throw error;setMessage('Check your email to confirm your account.');}
    else if(mode==='forgot'){const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}/auth/update-password`});if(error)throw error;setMessage('If an account exists, a reset link has been sent.');}
    else if(mode==='update-password'){const {error}=await supabase.auth.updateUser({password});if(error)throw error;nav('/');}
    else {const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;nav('/');}
  }catch(err:any){setMessage(err.message)}finally{setBusy(false)}}
  const title=mode==='register'?'Create your account':mode==='forgot'?'Reset your password':mode==='update-password'?'Choose a new password':'Welcome back';
  return <main className="auth-preview"><header className="auth-top"><img src="/assets/claritude-logo.svg" alt="Claritude"/><span>Privacy · Terms · Help</span></header><section className="login-card"><div className="login-heading"><img className="login-mark" src="/assets/claritude-favicon.svg" alt=""/><h1>{title}</h1><p>{mode==='register'?'Start monitoring your first property.':mode==='forgot'?'We will send a secure recovery link.':'Sign in to manage your websites.'}</p></div><form onSubmit={submit}>{mode!=='update-password'&&<label className="field">Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label>}{mode!=='forgot'&&<label className="field">{mode==='update-password'?'New password':'Password'}<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={10} autoComplete={mode==='register'?'new-password':'current-password'} required/></label>}<button className="primary login-submit" disabled={busy}>{busy?'Please wait…':title}</button>{message&&<div className="notice">{message}</div>}</form><div className="login-options">{mode==='sign-in'?<><Link to="/auth/forgot">Forgot password?</Link><Link to="/auth/register">Create account</Link></>:<Link to="/auth/sign-in">Back to sign in</Link>}</div></section></main>;
}

function Workspace({session}:{session:Session}){
  const [data,setData]=useState<Bootstrap|null>(null); const [error,setError]=useState('');
  const load=()=>api<Bootstrap>(session,'/api/bootstrap').then(setData).catch(e=>setError(e.message));
  useEffect(()=>{void load()},[]);
  if(error)return <State title="We could not load your workspace" detail={error} action={<button className="btn" onClick={load}>Try again</button>}/>;
  if(!data)return <Splash/>;
  if(!data.accounts?.length)return <Onboarding session={session} done={load}/>;
  return <Shell session={session} data={data} reload={load}/>;
}

function Onboarding({session,done}:{session:Session;done:()=>void}){
  const [step,setStep]=useState(1); const [accountName,setAccount]=useState(''); const [workspaceName,setWorkspace]=useState(''); const [propertyName,setProperty]=useState(''); const [url,setUrl]=useState('https://'); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  async function finish(){setBusy(true);try{await api(session,'/api/onboarding',{method:'POST',body:JSON.stringify({accountName,workspaceName,propertyName,url:url==='https://'?'':url})});done()}catch(e:any){setError(e.message)}finally{setBusy(false)}}
  return <main className="onboarding-preview"><header className="auth-top"><img src="/assets/claritude-logo.svg" alt="Claritude"/></header><div className="onboarding-shell"><aside className="onboarding-side"><h2>Get started</h2>{['Create account','Create workspace','Add property'].map((x,i)=><div className={`onboarding-progress ${step===i+1?'active':''} ${step>i+1?'complete':''}`} key={x}><span>{step>i+1?<Check/>:i+1}</span><b>{x}</b></div>)}</aside><section className="onboarding-card"><div className="onboarding-copy"><small className="eyebrow">Step {step} of 3</small>{step===1&&<><h1>Name your account</h1><p>The account owns access and future billing. Pro is included during early access.</p><label className="field">Account name<input autoFocus value={accountName} onChange={e=>setAccount(e.target.value)} placeholder="Your company"/></label></>}{step===2&&<><h1>Create your workspace</h1><p>A workspace keeps related properties and people together.</p><label className="field">Workspace name<input autoFocus value={workspaceName} onChange={e=>setWorkspace(e.target.value)} placeholder="Main workspace"/></label></>}{step===3&&<><h1>Add your first property</h1><p>Use a public website you control. You can also finish without adding one.</p><label className="field">Property name<input value={propertyName} onChange={e=>setProperty(e.target.value)} placeholder="Company website"/></label><label className="field">Website URL<input type="url" value={url} onChange={e=>setUrl(e.target.value)}/></label></>}</div>{error&&<div className="notice danger">{error}</div>}<div className="onboarding-actions">{step>1&&<button className="btn" onClick={()=>setStep(step-1)}>Back</button>}<span className="spacer"/><button className="primary" disabled={busy||step===1&&!accountName||step===2&&!workspaceName} onClick={()=>step<3?setStep(step+1):finish()}>{step<3?'Continue':busy?'Creating…':'Finish setup'}</button></div></section></div></main>;
}

const navItems=[['overview','Overview',LayoutGrid],['uptime','Uptime',Activity],['analytics','Analytics',BarChart3],['audit','Audit',ClipboardCheck],['reports','Reports',FileChartColumn]] as const;

function Shell({session,data,reload,fixture=false}:{session:Session|null;data:Bootstrap;reload:()=>void;fixture?:boolean}){
  const loc=useLocation(); const nav=useNavigate(); const [mobile,setMobile]=useState(false); const [addOpen,setAddOpen]=useState(false); const [userOpen,setUserOpen]=useState(false); const [toast,setToast]=useState('');
  const workspace:any=data.workspaces?.[0]?.workspaces; const propertyId=new URLSearchParams(loc.search).get('property')||data.properties?.[0]?.id; const property=data.properties.find(p=>p.id===propertyId); const section=loc.pathname.split('/')[1]||'dashboard';
  const notify:Notify=(message)=>{setToast(message);window.setTimeout(()=>setToast(''),2600)};
  const pageName=section==='dashboard'?'Overview':section==='account'?'Account settings':navItems.find(x=>x[0]===section)?.[1]||'Overview';
  const warning=property?.verification_status!=='verified'?{title:'Property verification is incomplete',detail:'Verify ownership to confirm installation and unlock trusted status.'}:property&&!property.tracking_last_received_at?{title:'Analytics is not receiving data',detail:'Install the tracking snippet or run the guided test.'}:data.notifications[0]?{title:data.notifications[0].title,detail:data.notifications[0].body}:null;
  function propertyLink(path:string,id=propertyId){return `/${path}${id?`?property=${id}`:''}`}
  return <div className="app"><header className="top"><button className="workspace top-selector" onClick={()=>setMobile(!mobile)}><Menu className="mobile-toggle"/><span className="avatar"><img src="/assets/websi-mark.svg" alt=""/></span><b>{workspace?.name||'Workspace'}</b><span className="badge">Pro</span><span className="chevs">⌃<br/>⌄</span></button><label className="selector"><span className="favicon"><Globe2/></span><select aria-label="Select property" value={propertyId||''} onChange={e=>e.target.value?nav(propertyLink(section==='dashboard'?'overview':section,e.target.value)):nav('/')}><option value="">Your properties</option>{data.properties.map(p=><option value={p.id} key={p.id}>{p.canonical_host}</option>)}</select><ChevronDown/></label><div className="page-title">{pageName}</div><div className="brand"><img src="/assets/claritude-logo.svg" alt="Claritude"/></div></header><div className="layout"><aside className={mobile?'open':''}><nav><Link className={section==='dashboard'?'active':''} to="/"><Globe2/>Your properties</Link>{property&&navItems.map(([path,label,Icon])=><Link className={section===path?'active':''} to={propertyLink(path)} key={path}><Icon/>{label}</Link>)}</nav><div className="nav-bottom"><nav>{property&&<Link className={section==='settings'?'active':''} to={propertyLink('settings')}><Settings/>Property Settings</Link>}<button onClick={()=>notify('Help centre opened')}><HelpCircle/>Help &amp; setup</button></nav>{userOpen&&<div className="user-popover"><Link to="/account" onClick={()=>setUserOpen(false)}><Users/>Account settings</Link><button onClick={()=>fixture?notify('Fixture mode does not sign out'):supabase.auth.signOut()}><LogOut/>Sign out</button></div>}<div className="user"><Link className="user-identity" to="/account"><span className="avatar user-avatar">{(data.profile?.full_name||session?.user.email||'C')[0].toUpperCase()}</span><b>{data.profile?.full_name||'Claritude user'}</b></Link><span className="spacer"/><button className="iconbtn" aria-label="Open account menu" onClick={()=>setUserOpen(!userOpen)}><MoreHorizontal/></button><button className="iconbtn" aria-label="Open notifications" onClick={()=>notify('Notification centre opened')}><Bell/></button></div></div></aside><main onClick={()=>setMobile(false)}>{warning&&<div className="warning"><span className="dot"/><b>{warning.title}</b><span className="subtle">{warning.detail}</span><span className="warning-actions"><Link className="text-link" to={propertyLink(property?.verification_status!=='verified'?'settings':'analytics')}>Review notification</Link></span></div>}<Routes><Route path="/" element={<Portfolio data={data} openAdd={()=>setAddOpen(true)}/>}/><Route path="/overview" element={<Overview session={session} property={property} notify={notify}/>}/><Route path="/uptime" element={<Uptime session={session} property={property} incidents={data.incidents} reload={reload} notify={notify}/>}/><Route path="/audit" element={<Audit session={session} property={property} notify={notify}/>}/><Route path="/analytics" element={<Analytics session={session} property={property} notify={notify}/>}/><Route path="/reports" element={<Reports session={session} property={property} notify={notify}/>}/><Route path="/settings" element={<PropertySettings session={session} property={property} reload={reload} notify={notify}/>}/><Route path="/account" element={<Account session={session} data={data} reload={reload} notify={notify}/>}/></Routes></main></div>{addOpen&&<AddProperty session={session} workspaceId={workspace?.id} close={()=>setAddOpen(false)} done={()=>{setAddOpen(false);reload();notify('Property added')}}/>}{toast&&<div className="toast">{toast}</div>}</div>;
}

function AddProperty({session,workspaceId,close,done}:{session:Session|null;workspaceId:string;close:()=>void;done:()=>void}){const [name,setName]=useState('');const [url,setUrl]=useState('https://');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function save(e:FormEvent){e.preventDefault();if(!session){done();return}setBusy(true);try{await api(session,'/api/properties',{method:'POST',body:JSON.stringify({workspaceId,name,url})});done()}catch(err:any){setError(err.message)}finally{setBusy(false)}}return <Modal title="Add property" close={close}><form onSubmit={save}><p className="subtle">Add a public website you own or manage. Monitoring starts after setup.</p><label className="field">Property name<input autoFocus value={name} onChange={e=>setName(e.target.value)} required/></label><label className="field">Website URL<input type="url" value={url} onChange={e=>setUrl(e.target.value)} required/></label>{error&&<div className="notice danger">{error}</div>}<div className="dialog-actions"><button type="button" className="btn" onClick={close}>Cancel</button><button className="primary" disabled={busy}>{busy?'Adding…':'Add property'}</button></div></form></Modal>}

function Portfolio({data,openAdd}:{data:Bootstrap;openAdd:()=>void}){const [query,setQuery]=useState('');const [tab,setTab]=useState('Properties');const rows=data.properties.filter(p=>(p.name+p.canonical_host).toLowerCase().includes(query.toLowerCase()));return <Page title="Your properties" actions={<button className="primary" onClick={openAdd}><Plus/>Add property</button>}><Tabs labels={['Properties','Traffic','Incidents','Reports','Members']} value={tab} onChange={setTab}/>{tab==='Properties'?<><Metrics values={[['Properties',data.properties.length,''],['Online',data.properties.filter(p=>p.uptime_monitors?.[0]?.last_status==='online').length,'Latest check'],['Open incidents',data.incidents.filter(i=>!i.resolved_at).length,'Needs attention'],['Early access','Pro','Included']]}/><section className="panel"><div className="toolbar"><div className="search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search properties"/></div><button className="btn"><Filter/>Filters</button></div><DataTable headers={['Property','Status','Uptime','Pageviews','Key events','Audit','Tracking']} rows={rows.map(p=>[<Link className="project-cell" to={`/overview?property=${p.id}`}><span className="favicon"><Globe2/></span><span><b>{p.name}</b><small className="subtle">{p.canonical_host}</small></span></Link>,<Status value={p.uptime_monitors?.[0]?.last_status||'pending'}/>,p.uptime_monitors?.[0]?.last_status==='online'?'Latest check passed':'—','—','—',p.audit_runs?.[0]?.score!=null?<span className="score">{p.audit_runs[0].score}</span>:'Not run',p.tracking_last_received_at?'Receiving data':'Not installed'])}/>{!rows.length&&<Empty title="No properties match these filters" detail="Clear the search or add another property."/>}</section></>:<StagePanel title={tab} detail={`${tab} across all properties will populate from measured production data. No demonstration totals are shown here.`}/>}</Page>}

function Overview({session,property,notify}:{session:Session|null;property?:Property;notify:Notify}){const [tab,setTab]=useState('Overview');const [analytics,setAnalytics]=useState<any>(null);useEffect(()=>{if(session&&property)api(session,`/api/properties/${property.id}/analytics?days=30`).then(setAnalytics).catch(()=>setAnalytics(null));else if(property)setAnalytics({pageviews:28460,events:358,pages:['/','/services/','/work/','/contact/']})},[property?.id]);if(!property)return <Empty title="Add your first property" detail="Properties appear here after setup."/>;const monitor=property.uptime_monitors?.[0];const audit=property.audit_runs?.[0];const pageviews=analytics?.pageviews||0;return <Page title="Property overview" status={<span className="period-chip"><CalendarDays/>Last 30 days</span>} actions={<Link className="primary" to={`/audit?property=${property.id}`}><RefreshCw/>Run audit</Link>}><Tabs labels={['Overview','Activity','Setup']} value={tab} onChange={setTab}/>{tab==='Overview'?<><div className="summary-note"><b>Latest audit:</b> {audit?fmtDate(audit.created_at):'not run'} · <b>Tracking:</b> {property.tracking_last_received_at?`received ${relative(property.tracking_last_received_at)}`:'not installed'} · <Link to={`/settings?property=${property.id}`}>Review setup</Link></div><Metrics values={[['Uptime',monitor?.last_status==='online'?'Online':cap(monitor?.last_status||'Pending'),monitor?.last_checked_at?`Checked ${relative(monitor.last_checked_at)}`:'Awaiting first check'],['Pageviews',fmtNum(pageviews),'Measured in this period'],['Key events',fmtNum(analytics?.events||0),'All accepted events'],['Audit',audit?.score!=null?`${audit.score} / 100`:'Not run',audit?.coverage!=null?`${audit.coverage}% catalogue coverage`:'']]}/><div className="grid"><div><Panel title="Traffic (last 30 days)" actions={<span className="seg"><button className="active">Pageviews</button><button onClick={()=>notify('Visitor estimates are not available yet')}>Daily visitors</button></span>}><Chart empty={!pageviews}/></Panel><Panel title="Website health"><div className="health-row"><Score value={audit?.score}/><div><b>{audit?.score!=null?'Latest audit completed':'No completed audit'}</b><small>{audit?.coverage!=null?`${audit.coverage}% of the active catalogue was evaluated.`:'Run an audit to populate evidence-backed checks.'}</small></div><Link className="btn" to={`/audit?property=${property.id}`}>Review audit</Link></div></Panel></div><div><Panel title="Real-user performance"><EmptyCompact title="No Core Web Vitals samples" detail="Performance appears after compatible browsers send measurements."/></Panel><Panel title="Top pages">{analytics?.pages?.length?<DataTable headers={['Page','Observed']} rows={analytics.pages.slice(0,5).map((p:string)=>[p,'Measured'])}/>:<EmptyCompact title="No page data yet" detail="Install tracking to identify top pages."/>}</Panel></div></div></>:tab==='Activity'?<Panel title="Recent property activity"><ActivityList property={property} monitor={monitor} audit={audit}/></Panel>:<SetupView property={property} monitor={monitor}/>}</Page>}

function Uptime({session,property,incidents,reload,notify}:{session:Session|null;property?:Property;incidents:any[];reload:()=>void;notify:Notify}){const [tab,setTab]=useState('Overview');const [busy,setBusy]=useState(false);const monitor=property?.uptime_monitors?.[0];const relevant=incidents.filter(i=>i.property_id===property?.id);async function check(){if(!monitor)return;setBusy(true);try{if(session)await api(session,`/api/monitors/${monitor.id}/check`,{method:'POST'});notify('Uptime check queued');window.setTimeout(reload,1500)}catch(e:any){notify(e.message)}finally{setBusy(false)}}if(!property)return <Empty title="Select a property" detail="Uptime monitoring is property-specific."/>;return <Page title="Uptime" status={<span className="period-chip"><CalendarDays/>Last 30 days</span>} actions={<button className="primary" disabled={!monitor||busy} onClick={check}><RefreshCw className={busy?'spin':''}/>{busy?'Checking…':'Check now'}</button>}><Tabs labels={['Overview','Incidents','Maintenance','Alerts','Monitor settings']} value={tab} onChange={setTab}/>{tab==='Overview'?<UptimeOverview monitor={monitor} incidents={relevant} setTab={setTab}/>:tab==='Incidents'?<Incidents incidents={relevant}/>:tab==='Maintenance'?<Maintenance notify={notify}/>:tab==='Alerts'?<AlertSettings notify={notify}/>:<MonitorSettings session={session} monitor={monitor} reload={reload} notify={notify}/>}</Page>}

function UptimeOverview({monitor,incidents,setTab}:{monitor?:Monitor;incidents:any[];setTab:(x:string)=>void}){const resolved=incidents.filter(i=>i.resolved_at);return <><Metrics values={[['Availability',monitor?.last_status==='online'?'Online':cap(monitor?.last_status||'Pending'),'Latest recorded state'],['Latest response',monitor?.last_response_ms?`${monitor.last_response_ms} ms`:'—','HTTP response'],['Resolved incidents',resolved.length,'Recorded history'],['Check interval',monitor?`${monitor.interval_minutes} min`:'—','']]}/><Panel title="30 day uptime" actions={<span><span className="status-dot online"/>Available &nbsp; <span className="status-dot down"/>Incident</span>}><div className="checkstrip">{Array.from({length:30},(_,i)=><i key={i} className={i===22&&incidents.length?'warn':''} title={i===22&&incidents.length?'Recorded incident':'No incident recorded'}/>)}</div></Panel><div className="grid three"><Panel title="Latest check"><KeyValues rows={[['Status',<Status value={monitor?.last_status||'pending'}/>],['Response',monitor?.last_response_ms?`${monitor.last_response_ms} ms`:'—'],['Checked',monitor?.last_checked_at?relative(monitor.last_checked_at):'Awaiting first check'],['Frequency',monitor?`Every ${monitor.interval_minutes} minutes`:'—']]}/></Panel><Panel title="Recent incidents">{incidents.length?<DataTable headers={['Opened','Cause','Status']} rows={incidents.slice(0,3).map(i=>[fmtDate(i.opened_at),i.cause||'Check failed',i.resolved_at?'Resolved':'Open'])}/>:<EmptyCompact title="No incidents recorded" detail="Confirmed failures will appear here."/>}<button className="btn panel-action" onClick={()=>setTab('Incidents')}>View incident details</button></Panel><Panel title="Monitor configuration"><KeyValues rows={[['Method','GET'],['Expected response',`${monitor?.expected_status_min||200}–${monitor?.expected_status_max||399}`],['Failure threshold',`${monitor?.failure_threshold||2} checks`],['Execution','Cloudflare queue worker']]}/><button className="btn panel-action" onClick={()=>setTab('Monitor settings')}>Open monitor settings</button></Panel></div></>}

function Incidents({incidents}:{incidents:any[]}){return <Panel title="Incident history" actions={<button className="btn"><Filter/>Filters</button>}>{incidents.length?incidents.map(i=><details className="incident-item" key={i.id}><summary><b>{fmtDate(i.opened_at)}</b> · {i.cause||'Check failed'} <span className="tag">{i.resolved_at?'Resolved':'Ongoing'}</span></summary><div className="incident-timeline"><span><i/><b>Failure detected</b><small>{fmtDate(i.opened_at)} · {i.cause||'Automated check failed'}</small></span><span><i/><b>Incident confirmed</b><small>Failure threshold reached</small></span><span className={i.resolved_at?'recovered':''}><i/><b>{i.resolved_at?'Recovery confirmed':'Awaiting recovery'}</b><small>{i.resolved_at?fmtDate(i.resolved_at):'Latest status remains unavailable'}</small></span></div></details>):<Empty title="No incidents recorded" detail="Confirmed failures and recoveries will appear here."/>}</Panel>}

function Maintenance({notify}:{notify:Notify}){const [windows,setWindows]=useState<{name:string;when:string}[]>([]);const [open,setOpen]=useState(false);return <><Panel title="Maintenance windows" actions={<button className="btn" onClick={()=>setOpen(true)}><Plus/>Add window</button>}>{windows.length?<DataTable headers={['Name','When','Alerts']} rows={windows.map(x=>[x.name,x.when,'Suppressed'])}/>:<Empty title="No scheduled windows" detail="Add one to document planned maintenance and suppress alerts."/>}</Panel>{open&&<MaintenanceDialog close={()=>setOpen(false)} save={x=>{setWindows(v=>[...v,x]);setOpen(false);notify('Maintenance window added for this session')}}/>}</>}
function MaintenanceDialog({close,save}:{close:()=>void;save:(x:{name:string;when:string})=>void}){const [name,setName]=useState('Planned maintenance');const [when,setWhen]=useState('');return <Modal title="Add maintenance window" close={close}><label className="field">Name<input value={name} onChange={e=>setName(e.target.value)}/></label><label className="field">Start time<input type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)}/></label><div className="notice">Stage 1 stores this draft in the current session; server-side maintenance persistence is listed as a limitation.</div><div className="dialog-actions"><button className="btn" onClick={close}>Cancel</button><button className="primary" disabled={!name||!when} onClick={()=>save({name,when})}>Add window</button></div></Modal>}
function AlertSettings({notify}:{notify:Notify}){const [email,setEmail]=useState('');const [rows,setRows]=useState<string[]>([]);return <div className="grid equal"><Panel title="Recipients">{rows.length?<DataTable headers={['Email','Down','Recovery']} rows={rows.map(x=>[x,'On','On'])}/>:<EmptyCompact title="No recipients configured" detail="Uptime events are still retained in the incident log."/>}<div className="inline-form"><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="alerts@example.com"/><button className="btn" disabled={!email} onClick={()=>{setRows(v=>[...v,email]);setEmail('');notify('Recipient added to this session')}}>Add recipient</button></div><p className="subtle">Recipient persistence is not yet enabled in the Stage 1 API.</p></Panel><Panel title="Alert policy"><KeyValues rows={[['Confirmation threshold','2 failed checks'],['Recovery alerts','Enabled'],['Email delivery','Configured server-side']]}/><button className="btn" onClick={()=>notify('Test alert recorded locally; no email was sent')}>Test alert flow</button></Panel></div>}

function MonitorSettings({session,monitor,reload,notify}:{session:Session|null;monitor?:Monitor;reload:()=>void;notify:Notify}){const [interval,setInterval]=useState(monitor?.interval_minutes||5);const [threshold,setThreshold]=useState(monitor?.failure_threshold||2);const [busy,setBusy]=useState(false);async function save(enabled=monitor?.enabled!==false){if(!monitor)return;setBusy(true);try{if(session)await api(session,`/api/monitors/${monitor.id}`,{method:'PATCH',body:JSON.stringify({enabled,interval_minutes:interval,timeout_ms:monitor.timeout_ms||10000,expected_status_min:monitor.expected_status_min||200,expected_status_max:monitor.expected_status_max||399,failure_threshold:threshold})});notify(enabled?'Monitor settings saved':'Monitoring paused');reload()}catch(e:any){notify(e.message)}finally{setBusy(false)}}return <Panel title="Monitor settings"><div className="form-two"><label className="field">Check interval<select value={interval} onChange={e=>setInterval(Number(e.target.value))}>{[5,10,15,30,60].map(x=><option value={x} key={x}>{x} minutes</option>)}</select></label><label className="field">Confirm after<select value={threshold} onChange={e=>setThreshold(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option value={x} key={x}>{x} failed check{x>1?'s':''}</option>)}</select></label></div><KeyValues rows={[['Timeout',`${(monitor?.timeout_ms||10000)/1000} seconds`],['Method','GET'],['Expected response',`HTTP ${monitor?.expected_status_min||200}–${monitor?.expected_status_max||399}`],['Execution','Distributed queue worker']]}/><div className="settings-actions"><button className="primary" disabled={!monitor||busy} onClick={()=>save(true)}>Save monitor settings</button><button className="btn danger" disabled={!monitor||busy} onClick={()=>save(monitor?.enabled===false)}>{monitor?.enabled===false?<><Activity/>Resume monitoring</>:<><Pause/>Pause monitoring</>}</button></div></Panel>}

function Audit({session,property,notify}:{session:Session|null;property?:Property;notify:Notify}){const [runs,setRuns]=useState<AuditRun[]>([]);const [tab,setTab]=useState('Overview');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [filter,setFilter]=useState('All');const load=()=>property&&(session?api<AuditRun[]>(session,`/api/properties/${property.id}/audits`).then(setRuns).catch(e=>setError(e.message)):setRuns([fixtureAudit()]));useEffect(()=>{load()},[property?.id]);async function start(){if(!property)return;setBusy(true);try{if(session)await api(session,'/api/audits',{method:'POST',body:JSON.stringify({propertyId:property.id})});notify('Audit queued');await load()}catch(e:any){setError(e.message)}finally{setBusy(false)}}if(!property)return <Empty title="Select a property" detail="Audits are run against a selected property."/>;const latest=runs[0];const results=latest?.audit_results||[];const partial=(latest?.coverage??0)<80;const visible=filter==='All'?results:results.filter((x:any)=>(x.category||x.status||'').toLowerCase().includes(filter.toLowerCase()));return <Page title="Audit" actions={<button className="primary" disabled={busy} onClick={start}><RefreshCw/>{busy?'Queuing…':'Run audit'}</button>}><div className="audit-nav-row"><button className="audit-page-picker"><Globe2/><span><b>{property.name}</b><small>{new URL(property.url).pathname||'/'}</small></span><ChevronDown/></button><Tabs labels={['Overview','Findings','Checks','History','Compare']} value={tab} onChange={setTab}/></div>{error&&<div className="notice danger">{error}</div>}{latest&&<div className={`coverage-note ${partial?'partial':''}`}><b>{partial?'Partial catalogue coverage':'Catalogue coverage complete'}</b><span>{latest.coverage??0}% of the active audit catalogue produced evidence. {partial?'The score is labelled partial and should not be treated as a complete site grade.':'Results are evidence-backed for this run.'}</span></div>}{tab==='Overview'?<><AuditScore run={latest}/><div className="grid"><Panel title="Fix these first">{results.length?<AuditResults results={results.slice(0,6)}/>:<Empty title="No findings available" detail={latest?.status==='completed'?'This run returned no detailed findings.':'Run an audit to generate evidence-backed findings.'}/>}</Panel><Panel title="Run details"><KeyValues rows={[['Status',cap(latest?.status||'Not run')],['Page',latest?.page_url||property.url],['Started',latest?fmtDate(latest.created_at):'Never'],['Duration',latest?.duration_ms?`${latest.duration_ms} ms`:'—'],['Catalogue coverage',latest?.coverage!=null?`${latest.coverage}%`:'—']]}/></Panel></div></>:tab==='Findings'?<Panel title="Findings" actions={<select value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>SEO</option><option>Performance</option><option>Security</option><option>Accessibility</option></select>}>{visible.length?<AuditResults results={visible}/>:<Empty title="No findings match" detail="Choose another category or run a new audit."/>}</Panel>:tab==='Checks'?<Panel title="Checks"><DataTable headers={['Check','Category','Result','Evidence']} rows={results.map((x:any)=>[x.title||x.check_id,x.category||'General',cap(x.status||x.outcome||'Recorded'),typeof x.evidence==='string'?x.evidence:'Evidence stored'])}/></Panel>:tab==='History'?<Panel title="Audit history"><DataTable headers={['Started','Page','Status','Score','Coverage','Duration']} rows={runs.map(r=>[fmtDate(r.created_at),r.page_url||property.url,cap(r.status),r.score!=null?`${r.score}${(r.coverage??0)<80?' · partial':''}`:'—',r.coverage!=null?`${r.coverage}%`:'—',r.duration_ms?`${r.duration_ms} ms`:'—'])}/></Panel>:<CompareAudits runs={runs}/>}</Page>}

function AuditScore({run}:{run?:AuditRun}){const score=run?.score;return <div className="audit-score-row"><div className="audit-score"><span>{score??'—'}</span><small>{score!=null&&((run?.coverage??0)<80)?'Partial score':'Overall'}</small></div><div className="audit-six-stats">{['SEO','Performance','Accessibility','Security','Infrastructure','AI readiness'].map(x=><div className="audit-six-stat" key={x}><small>{x}</small><b>—</b><span className="subtle">Not split by current engine</span></div>)}</div></div>}
function AuditResults({results}:{results:any[]}){return <div>{results.map((x,i)=><details className="audit-item" key={x.id||x.check_id||i}><summary><span className={`severity ${severity(x)}`}>{severity(x)==='pass'?<CheckCircle2/>:<CircleAlert/>}</span><span><b>{x.title||x.check_id||'Audit check'}</b><small className="subtle">{x.category||'General'} · {cap(x.status||x.outcome||'Recorded')}</small></span></summary><div className="audit-detail"><b>Evidence</b><code>{typeof x.evidence==='string'?x.evidence:JSON.stringify(x.evidence||{},null,2)}</code>{x.message&&<p>{x.message}</p>}<button className="btn"><RefreshCw/>Re-test in next audit</button></div></details>)}</div>}
function CompareAudits({runs}:{runs:AuditRun[]}){return <Panel title="Compare completed audits">{runs.length<2?<Empty title="Two completed runs are required" detail="Run another audit to compare score, coverage and duration."/>:<DataTable headers={['Metric',fmtDate(runs[1].created_at),fmtDate(runs[0].created_at),'Change']} rows={[['Score',runs[1].score??'—',runs[0].score??'—',delta(runs[0].score,runs[1].score)],['Coverage',`${runs[1].coverage??0}%`,`${runs[0].coverage??0}%`,delta(runs[0].coverage,runs[1].coverage)],['Duration',`${runs[1].duration_ms??0} ms`,`${runs[0].duration_ms??0} ms`,delta(runs[0].duration_ms,runs[1].duration_ms)]]}/>}</Panel>}

function Analytics({session,property,notify}:{session:Session|null;property?:Property;notify:Notify}){const [data,setData]=useState<any>(null);const [tab,setTab]=useState('Overview');useEffect(()=>{if(!property)return;if(session)api(session,`/api/properties/${property.id}/analytics?days=30`).then(setData).catch(()=>setData(null));else setData({pageviews:28460,events:358,pages:['/','/services/','/work/','/contact/']})},[property?.id]);if(!property)return <Empty title="Select a property" detail="Analytics is property-specific."/>;const snippet=`<script defer src="${location.origin}/tracker.js" data-property="${property.tracking_id}"></script>`;const active=!!property.tracking_last_received_at;return <Page title="Analytics" status={<span className="period-chip"><CalendarDays/>Last 30 days</span>}><Tabs labels={['Overview','Pages','Sources','Events','Audience','Engagement','Performance']} value={tab} onChange={setTab}/>{tab==='Overview'?<><Metrics values={[['Pageviews',fmtNum(data?.pageviews||0),'Accepted pageview events'],['Events',fmtNum(data?.events||0),'All accepted events'],['Observed pages',data?.pages?.length||0,'Unique paths in period'],['Last received',active?relative(property.tracking_last_received_at!):'Never','']]}/>{active?<><Panel title="Traffic" actions={<span className="seg"><button className="active">Pageviews</button><button onClick={()=>notify('Daily visitor estimates are not available yet')}>Daily visitors</button></span>}><div className="chart-legend"><span>Current period</span><span className="previous">Previous period unavailable</span></div><Chart empty={!data?.pageviews}/></Panel><div className="grid equal"><Panel title="Top pages">{data?.pages?.length?<DataTable headers={['Page','Status']} rows={data.pages.map((p:string)=>[p,'Observed'])}/>:<EmptyCompact title="No pages observed" detail="Page paths appear after the first pageview."/>}</Panel><Panel title="Data quality"><KeyValues rows={[['Public property ID',property.tracking_id],['Allowed host',property.canonical_host],['Last event',relative(property.tracking_last_received_at!)],['Cookies','None'],['Persistent visitor IDs','None']]}/></Panel></div></>:<TrackingSetup property={property} snippet={snippet} notify={notify}/>}</>:tab==='Pages'?<Panel title="Pages">{data?.pages?.length?<DataTable headers={['Page','Observed in period','Open']} rows={data.pages.map((p:string)=>[p,'Yes',<a className="iconbtn" href={`${property.url.replace(/\/$/,'')}${p}`} target="_blank" rel="noreferrer"><ExternalLink/></a>])}/>:<Empty title="No page data yet" detail="Install tracking and load the website to record page paths."/>}</Panel>:tab==='Events'?<Panel title="Events"><KeyValues rows={[['Accepted events',fmtNum(data?.events||0)],['Pageviews',fmtNum(data?.pageviews||0)],['Other event types',fmtNum(Math.max(0,(data?.events||0)-(data?.pageviews||0)))]]}/><Link className="btn" to={`/settings?property=${property.id}`}>Open event setup</Link></Panel>:<StagePanel title={tab} detail={`${tab} breakdowns require additional aggregate dimensions. The current Stage 1 API does not fabricate them.`}/>}</Page>}

function TrackingSetup({property,snippet,notify}:{property:Property;snippet:string;notify:Notify}){async function copy(){await navigator.clipboard.writeText(snippet);notify('Analytics code copied')}return <><div className="grid equal"><Panel title="Install analytics once"><p>Add the script to the site-wide <code>&lt;head&gt;</code> template so it loads once on every measured page.</p><pre className="install-code">{snippet}</pre><div className="settings-actions"><button className="btn" onClick={copy}><Copy/>Copy analytics code</button><button className="btn" onClick={()=>window.open(property.url,'_blank','noopener,noreferrer')}><ExternalLink/>Open website</button></div><p className="subtle">No cookies, persistent visitor IDs, form contents or sensitive query strings are collected.</p></Panel><Panel title="Installation status"><KeyValues rows={[['Public property ID',property.tracking_id],['Allowed domain',property.canonical_host],['Script','Not detected'],['Data status','Awaiting first event'],['Last received','Never']]}/><Link className="btn" to={`/settings?property=${property.id}`}>Troubleshoot installation</Link></Panel></div><Panel title="Onboarding checklist"><div className="onboarding-list">{[['Property added',true],['Property verified',property.verification_status==='verified'],['Analytics receiving data',false],['First audit completed',!!property.audit_runs?.length]].map(([label,ok])=><span key={String(label)}>{ok?<CheckCircle2/>:<CircleAlert/>}{label}</span>)}</div></Panel></>}

function Reports({session,property,notify}:{session:Session|null;property?:Property;notify:Notify}){const [tab,setTab]=useState('Quick reports');const [report,setReport]=useState<any>();async function preview(name='Monthly website health'){if(!property)return;if(session)setReport(await api(session,`/api/properties/${property.id}/report`));else setReport({generatedAt:new Date().toISOString(),period:'Last 30 days',property,limitations:['Local reference fixture']});notify(`${name} preview generated`)}return <Page title="Reports" actions={<button className="primary" onClick={()=>preview()} disabled={!property}>Create report</button>}><Tabs labels={['Quick reports','Saved reports','Schedules','Branding']} value={tab} onChange={setTab}/>{tab==='Quick reports'?<div className="grid equal">{['Monthly overview','Uptime & incidents','Audit & fixes','Traffic & events','Visitor performance','Client summary'].map(x=><Panel title={x} key={x}><p className="subtle">Generate from the selected property’s measured data and declared limitations.</p><button className="btn" onClick={()=>preview(x)}>Use template</button></Panel>)}</div>:tab==='Saved reports'?<Panel title="Saved reports">{report?<DataTable headers={['Report','Property','Period','Generated','']} rows={[[`Generated property report`,property?.canonical_host,report.period,fmtDate(report.generatedAt),<button className="btn" onClick={()=>notify('Report preview is already open below')}>View details</button>]]}/>:<Empty title="No saved reports" detail="Generate a quick report to preview its evidence."/>}</Panel>:tab==='Schedules'?<Panel title="Report schedules"><Empty title="Scheduling is not enabled in Stage 1" detail="Reports can be generated on demand; the interface does not claim emails were sent."/></Panel>:<div className="grid equal"><Panel title="Report branding"><p>Claritude branding is applied to Stage 1 report previews.</p><button className="btn" onClick={()=>notify('Brand preview updated')}>Preview branding</button></Panel><Panel title="Preview"><img className="report-logo" src="/assets/claritude-logo.svg" alt="Claritude"/><p><b>{property?.name||'Property'} performance report</b></p><p className="subtle">Powered by Claritude</p></Panel></div>}{report&&<Panel title={`${report.property.name} · ${report.period}`} actions={<button className="iconbtn" onClick={()=>setReport(undefined)}><X/></button>}><div className="report-summary"><b>Generated {fmtDate(report.generatedAt)}</b><p>{report.limitations?.join(' ')}</p><pre>{JSON.stringify({uptime:report.incidents?.length||0,audits:report.audits?.length||0,analytics:report.analytics||{}},null,2)}</pre></div></Panel>}</Page>}

function PropertySettings({session,property,reload,notify}:{session:Session|null;property?:Property;reload:()=>void;notify:Notify}){const [tab,setTab]=useState('General');if(!property)return <Empty title="Select a property" detail="Property settings require a selected property."/>;return <Page title="Property settings" status={<Status value={property.uptime_monitors?.[0]?.last_status||'pending'}/>}><Tabs labels={['General','Tracking','Uptime','Events','Sharing','Advanced']} value={tab} onChange={setTab}/>{tab==='General'?<GeneralSettings session={session} property={property} reload={reload} notify={notify}/>:tab==='Tracking'?<TrackingSettings property={property} notify={notify}/>:tab==='Uptime'?<MonitorSettings session={session} monitor={property.uptime_monitors?.[0]} reload={reload} notify={notify}/>:tab==='Events'?<EventSettings property={property} notify={notify}/>:tab==='Sharing'?<StagePanel title="Sharing" detail="Property viewers and roles are managed at account level. Stage 1 does not simulate invitations."/>:<Panel title="Advanced"><div className="advanced-row"><span><b>Property verification</b><small>Check the public site for this property’s tracking identifier.</small></span><VerifyButton session={session} property={property} reload={reload} notify={notify}/></div><div className="advanced-row"><span><b>Website URL</b><small>{property.url} · fixed after setup</small></span><Status value={property.verification_status}/></div><div className="advanced-row"><span><b>Delete property</b><small>Destructive controls are intentionally unavailable in Stage 1.</small></span><button className="btn danger" disabled>Unavailable</button></div></Panel>}</Page>}

function GeneralSettings({session,property,reload,notify}:{session:Session|null;property:Property;reload:()=>void;notify:Notify}){const [name,setName]=useState(property.name);const [busy,setBusy]=useState(false);async function save(){setBusy(true);try{if(session)await api(session,`/api/properties/${property.id}`,{method:'PATCH',body:JSON.stringify({name})});notify('General settings saved');reload()}catch(e:any){notify(e.message)}finally{setBusy(false)}}return <Panel title="General"><label className="field">Property name<input value={name} onChange={e=>setName(e.target.value)}/></label><label className="field">Website URL<input className="readonly" value={property.url} readOnly/><small className="subtle">The monitored URL is fixed after setup. Create another property for a different domain.</small></label><div className="form-two"><label className="field">Timezone<select defaultValue="Europe/London"><option>Europe/London</option></select></label><label className="field">Reporting currency<select defaultValue="GBP"><option value="GBP">GBP (£)</option></select></label></div><div className="settings-actions right"><button className="primary" disabled={busy||!name.trim()||name===property.name} onClick={save}>{busy?'Saving…':'Save general settings'}</button></div></Panel>}
function TrackingSettings({property,notify}:{property:Property;notify:Notify}){const snippet=`<script defer src="${location.origin}/tracker.js" data-property="${property.tracking_id}"></script>`;return <TrackingSetup property={property} snippet={snippet} notify={notify}/>}
function EventSettings({property,notify}:{property:Property;notify:Notify}){const click='data-claritude-event="enquiry-submit-click"';const success=`claritude.event('successful-form-submission', { page: '/contact/' });`;return <><div className="grid equal"><Panel title="Button and link clicks"><p>Add this attribute to the clicked element. It records the interaction, not the downstream result.</p><pre className="install-code">{click}</pre><button className="btn" onClick={()=>navigator.clipboard.writeText(click).then(()=>notify('Click attribute copied'))}><Copy/>Copy click attribute</button></Panel><Panel title="Successful form submissions"><p>Fire only after the server or form provider confirms success.</p><pre className="install-code">{success}</pre><button className="btn" onClick={()=>navigator.clipboard.writeText(success).then(()=>notify('Success event copied'))}><Copy/>Copy success event</button></Panel></div><Panel title="Event test panel"><KeyValues rows={[['Property ID',property.tracking_id],['Last received',property.tracking_last_received_at?relative(property.tracking_last_received_at):'Never'],['Privacy','No form values are collected']]}/></Panel></>}
function VerifyButton({session,property,reload,notify}:{session:Session|null;property:Property;reload:()=>void;notify:Notify}){const [busy,setBusy]=useState(false);async function verify(){setBusy(true);try{const result=session?await api<any>(session,`/api/properties/${property.id}/verify`,{method:'POST'}):{verified:true};notify(result.verified?'Property verified':'Verification marker not found');reload()}catch(e:any){notify(e.message)}finally{setBusy(false)}}return <button className="btn" disabled={busy} onClick={verify}><RefreshCw/>{busy?'Checking…':'Verify now'}</button>}

function Account({session,data,reload,notify}:{session:Session|null;data:Bootstrap;reload:()=>void;notify:Notify}){const [tab,setTab]=useState('Profile');const role=data.accounts?.[0]?.role||'member';const tabs=role==='owner'?['Profile','Workspace','Billing & plan','Users','Notification preferences','Activity logs','Security','Data & privacy']:['Profile','Notification preferences','Security'];return <Page title="Account settings" status={<span className="tag">{role==='owner'?'Account holder':cap(role)}</span>}><Tabs labels={tabs} value={tab} onChange={setTab}/>{tab==='Profile'?<Profile session={session} data={data} reload={reload} notify={notify}/>:tab==='Workspace'?<Panel title="Workspace"><DataTable headers={['Workspace','Properties','Access']} rows={data.workspaces.map((w:any)=>[w.workspaces?.name||'Workspace',data.properties.length,cap(w.role||'member')])}/></Panel>:tab==='Billing & plan'?<Billing/>:tab==='Users'?<Panel title="Workspace users"><DataTable headers={['User','Access','Scope']} rows={[[data.profile?.full_name||'Current user',cap(role),'All properties']]}/><p className="subtle">Invitation and paid-seat management are not enabled in Stage 1.</p></Panel>:tab==='Notification preferences'?<Preferences notify={notify}/>:tab==='Activity logs'?<Panel title="Account activity logs"><Empty title="Activity log feed is not exposed by the Stage 1 API" detail="Security-sensitive actions remain protected in the database."/></Panel>:tab==='Security'?<Security session={session} notify={notify}/>:<Panel title="Data & privacy"><div className="privacy-row"><span><b>Export account data</b><small>Self-service export is planned beyond Stage 1.</small></span><button className="btn" disabled>Not available</button></div><div className="privacy-row danger-zone"><span><b>Delete account</b><small>Contact support for destructive account operations.</small></span><button className="btn danger" disabled>Not available</button></div></Panel>}</Page>}
function Profile({session,data,reload,notify}:{session:Session|null;data:Bootstrap;reload:()=>void;notify:Notify}){const [name,setName]=useState(data.profile?.full_name||'');const [timezone,setTimezone]=useState(data.profile?.timezone||'Europe/London');const [busy,setBusy]=useState(false);async function save(){setBusy(true);try{if(session)await api(session,'/api/profile',{method:'PATCH',body:JSON.stringify({full_name:name,timezone})});notify('Profile saved');reload()}catch(e:any){notify(e.message)}finally{setBusy(false)}}return <Panel title="Personal profile"><div className="profile-identity"><span className="avatar profile-avatar">{(name||'C')[0].toUpperCase()}</span><span><h2>{name||'Claritude user'}</h2><small className="subtle">Personal profile</small></span></div><label className="field">Display name<input value={name} onChange={e=>setName(e.target.value)}/></label><label className="field">Email<input value={session?.user.email||'Local fixture'} readOnly/></label><label className="field">Timezone<select value={timezone} onChange={e=>setTimezone(e.target.value)}><option>Europe/London</option><option>UTC</option></select></label><button className="primary" disabled={busy} onClick={save}>{busy?'Saving…':'Save profile'}</button></Panel>}
function Billing(){return <><div className="grid equal"><Panel title="Subscription"><span className="tag">Early access</span><div className="price">Pro</div><p className="subtle">Pro access is included during early access. No charge is represented by this interface.</p></Panel><Panel title="Usage"><KeyValues rows={[['Properties','Measured from workspace'],['Analytics events','Usage billing not active'],['Audits','Usage billing not active'],['Editing seats','Not enforced in Stage 1']]}/></Panel></div><Panel title="Choose a plan"><div className="plans">{['Free','Essentials','Scale','Pro'].map(x=><div className={`plan ${x==='Pro'?'current':''}`} key={x}><h2>{x}</h2><p className="subtle">{x==='Pro'?'Current early-access entitlement':'Plan changes are not available in Stage 1.'}</p><button className="btn" disabled>{x==='Pro'?'Current plan':'Unavailable'}</button></div>)}</div></Panel></>}
function Preferences({notify}:{notify:Notify}){return <Panel title="Notification preferences">{['Monitor incidents','Recoveries','Tracking problems','Audit issues','Billing & subscription','Account security'].map(x=><label className="pref-row" key={x}><input type="checkbox" defaultChecked onChange={()=>notify(`${x} preference updated for this session`)}/><span>{x}</span></label>)}</Panel>}
function Security({session,notify}:{session:Session|null;notify:Notify}){return <div className="grid equal"><Panel title="Password"><p>Use the secure recovery flow to change your password.</p><Link className="primary" to="/auth/forgot">Request reset link</Link></Panel><Panel title="Sessions"><KeyValues rows={[['This browser','Current authenticated session'],['Last active','Now']]}/><button className="btn" onClick={()=>session?supabase.auth.signOut():notify('Fixture mode does not have a session')}>Sign out this session</button></Panel></div>}

function Page({title,status,actions,children}:{title:string;status?:ReactNode;actions?:ReactNode;children:ReactNode}){return <div className="content"><div className="title-row"><h1>{title}</h1>{status}<span className="spacer"/>{actions}<button className="iconbtn" aria-label="Page options"><MoreHorizontal/></button></div>{children}</div>}
function Tabs({labels,value,onChange}:{labels:string[];value:string;onChange:(x:string)=>void}){return <div className="tabs" role="tablist">{labels.map(x=><button role="tab" aria-selected={value===x} className={value===x?'active':''} onClick={()=>onChange(x)} key={x}>{x}</button>)}</div>}
function Metrics({values}:{values:(string|number)[][]}){return <div className="metrics">{values.map((v,i)=><div className="metric" key={i}><small>{v[0]}</small><b>{v[1]}</b><span>{v[2]}</span></div>)}</div>}
function Panel({title,actions,children,className=''}:{title:string;actions?:ReactNode;children:ReactNode;className?:string}){return <section className={`panel ${className}`}><div className="panel-head"><h2>{title}</h2><span className="spacer"/>{actions}</div>{children}</section>}
function DataTable({headers,rows}:{headers:string[];rows:ReactNode[][]}){return <div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((x,j)=><td key={j}>{x}</td>)}</tr>)}</tbody></table></div>}
function KeyValues({rows}:{rows:[string,ReactNode][]}){return <div className="key-values">{rows.map(([k,v])=><div className="kv" key={k}><span className="subtle">{k}</span><b>{v}</b></div>)}</div>}
function Status({value}:{value:string}){const v=(value||'pending').toLowerCase();return <span className="status-label"><i className={`status-dot ${['online','verified','receiving'].includes(v)?'online':v==='offline'?'down':'paused'}`}/>{cap(value)}</span>}
function Score({value}:{value?:number}){return <span className="large-score">{value??'—'}</span>}
function Empty({title,detail}:{title:string;detail:string}){return <div className="empty-state"><Globe2/><b>{title}</b><small>{detail}</small></div>}
function EmptyCompact({title,detail}:{title:string;detail:string}){return <div className="empty-compact"><b>{title}</b><small>{detail}</small></div>}
function StagePanel({title,detail}:{title:string;detail:string}){return <Panel title={title}><Empty title={`No ${title.toLowerCase()} data yet`} detail={detail}/></Panel>}
function Chart({empty=false}:{empty?:boolean}){if(empty)return <Empty title="No measured traffic yet" detail="The chart will populate after pageviews are received."/>;const points='0,160 55,142 110,149 165,112 220,122 275,90 330,98 385,62 440,78 495,44 550,53 605,27 660,38 715,18 770,31 825,10';return <svg className="chart" viewBox="0 0 825 190" preserveAspectRatio="none" aria-label="Traffic chart"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#00c989" stopOpacity=".22"/><stop offset="1" stopColor="#00c989" stopOpacity="0"/></linearGradient></defs>{[30,70,110,150].map(y=><line className="chart-grid" x1="0" x2="825" y1={y} y2={y} key={y}/>)}<polyline className="compare" points="0,170 55,160 110,144 165,135 220,128 275,121 330,108 385,101 440,90 495,80 550,68 605,61 660,51 715,42 770,34 825,28"/><polygon className="area" points={`0,190 ${points} 825,190`}/><polyline className="series" points={points}/></svg>}
function ActivityList({property,monitor,audit}:{property:Property;monitor?:Monitor;audit?:AuditRun}){const items=[[monitor?.last_checked_at,'Uptime check completed',monitor?.last_status],[audit?.created_at,'Audit run created',audit?.status],[property.tracking_last_received_at,'Analytics event received','accepted']].filter(x=>x[0]);return items.length?<ul className="activity-list">{items.map((x,i)=><li key={i}><span className="status-dot online"/><span><b>{x[1]}</b><small>{relative(String(x[0]))} · {cap(String(x[2]))}</small></span></li>)}</ul>:<Empty title="No recent activity" detail="Checks, audits and tracking events will appear here."/>}
function SetupView({property,monitor}:{property:Property;monitor?:Monitor}){return <Panel title="Onboarding checklist"><div className="onboarding-list large">{[[property.verification_status==='verified','Property verified'],[!!monitor,'Uptime monitoring enabled'],[!!property.tracking_last_received_at,'Analytics receiving data'],[!!property.audit_runs?.length,'First audit completed']].map(([ok,label])=><span key={String(label)}>{ok?<CheckCircle2/>:<CircleAlert/>}<b>{label}</b><small>{ok?'Complete':'Needs attention'}</small></span>)}</div></Panel>}
function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}){return <div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="dialog" role="dialog" aria-modal="true"><div className="panel-head"><h2>{title}</h2><span className="spacer"/><button className="iconbtn" onClick={close} aria-label="Close"><X/></button></div>{children}</section></div>}
function State({title,detail,action}:{title:string;detail:string;action?:ReactNode}){return <main className="state"><CircleAlert/><h1>{title}</h1><p>{detail}</p>{action}</main>}
function Splash(){return <main className="splash"><img src="/assets/claritude-favicon.svg" alt=""/><span/></main>}
function fmtDate(x:string){return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x))}
function relative(x:string){const seconds=Math.max(1,Math.round((Date.now()-new Date(x).getTime())/1000));if(seconds<60)return `${seconds} seconds ago`;if(seconds<3600)return `${Math.floor(seconds/60)} minutes ago`;if(seconds<86400)return `${Math.floor(seconds/3600)} hours ago`;return `${Math.floor(seconds/86400)} days ago`}
function fmtNum(x:number){return new Intl.NumberFormat('en-GB').format(x||0)}
function cap(x:string){return x?x.charAt(0).toUpperCase()+x.slice(1).replaceAll('_',' '):'—'}
function severity(x:any){const value=String(x.status||x.outcome||'').toLowerCase();return value.includes('pass')?'pass':value.includes('warn')?'warning':'critical'}
function delta(a?:number,b?:number){if(a==null||b==null)return '—';const d=a-b;return d===0?'No change':`${d>0?'+':''}${d}`}
function fixtureAudit():AuditRun{return {id:'fixture-audit',status:'completed',score:87,coverage:100,page_url:'https://websi.com/',created_at:new Date(Date.now()-86400000).toISOString(),duration_ms:2840,audit_results:[{id:'1',check_id:'seo.title',title:'Page title is descriptive',category:'SEO',status:'passed',evidence:'<title>Websi — Digital experiences</title>'},{id:'2',check_id:'performance.hero',title:'Hero image can load earlier',category:'Performance',status:'warning',evidence:'Largest image was not preloaded'},{id:'3',check_id:'security.headers',title:'Content security policy is incomplete',category:'Security',status:'failed',evidence:'content-security-policy header missing'}]}}
